	/* @Override */
	protected bool refresh(DBRecord associationRecord) {
		if (associationRecord == null) {
			associationRecord = associationDBM.getAssociationRecord(key);
		}
		if (associationRecord == null) {
			return false;
		}
		record = associationRecord;
		return true;
